// DPLL with two-watched-literal propagation — a line-by-line port of
// internal/catalog/sat.go. Both solvers consume the same canonical CNF from
// GET /v1/catalog/{version}/cnf; sat.test.ts checks agreement on cases
// generated by the Go implementation.

export type Lit = number;

export interface CNF {
  numVars: number;
  clauses: Lit[][];
}

export interface Formula {
  catalogVersion: string;
  base: string;
  arch: string;
  vars: string[];
  cnf: CNF;
  groups: Record<string, string[]>;
  origins: string[];
}

class Solver {
  n: number;
  clauses: Lit[][] = [];
  watches = new Map<Lit, number[]>();
  assign: Int8Array;
  trail: Lit[] = [];
  units: Lit[] = [];
  empty = false;

  constructor(f: CNF) {
    this.n = f.numVars;
    this.assign = new Int8Array(f.numVars + 1);
    for (const raw of f.clauses) {
      const cl = dedupe(raw);
      if (cl === null) continue;
      if (cl.length === 0) this.empty = true;
      else if (cl.length === 1) this.units.push(cl[0]);
      else {
        const idx = this.clauses.length;
        this.clauses.push(cl);
        this.watch(cl[0], idx);
        this.watch(cl[1], idx);
      }
    }
  }

  private watch(l: Lit, ci: number) {
    const w = this.watches.get(l);
    if (w) w.push(ci);
    else this.watches.set(l, [ci]);
  }

  value(l: Lit): number {
    const v = this.assign[Math.abs(l)];
    return l < 0 ? -v : v;
  }

  set(l: Lit) {
    this.assign[Math.abs(l)] = l > 0 ? 1 : -1;
    this.trail.push(l);
  }

  propagate(qhead: number): boolean {
    while (qhead < this.trail.length) {
      const falseLit = -this.trail[qhead];
      qhead++;
      const ws = this.watches.get(falseLit) ?? [];
      const kept: number[] = [];
      let conflict = false;
      for (let i = 0; i < ws.length; i++) {
        const ci = ws[i];
        if (conflict) {
          kept.push(ci);
          continue;
        }
        const cl = this.clauses[ci];
        if (cl[0] === falseLit) [cl[0], cl[1]] = [cl[1], cl[0]];
        if (this.value(cl[0]) === 1) {
          kept.push(ci);
          continue;
        }
        let moved = false;
        for (let k = 2; k < cl.length; k++) {
          if (this.value(cl[k]) !== -1) {
            [cl[1], cl[k]] = [cl[k], cl[1]];
            this.watch(cl[1], ci);
            moved = true;
            break;
          }
        }
        if (moved) continue;
        kept.push(ci);
        const v0 = this.value(cl[0]);
        if (v0 === -1) conflict = true;
        else if (v0 === 0) this.set(cl[0]);
      }
      this.watches.set(falseLit, kept);
      if (conflict) return false;
    }
    return true;
  }

  undo(to: number) {
    while (this.trail.length > to) {
      const l = this.trail.pop()!;
      this.assign[Math.abs(l)] = 0;
    }
  }

  assume(lits: Lit[]): boolean {
    for (const l of lits) {
      const v = this.value(l);
      if (v === -1) return false;
      if (v === 1) continue;
      const start = this.trail.length;
      this.set(l);
      if (!this.propagate(start)) return false;
    }
    return true;
  }

  search(): boolean {
    let v = 0;
    for (let i = 1; i <= this.n; i++) {
      if (this.assign[i] === 0) {
        v = i;
        break;
      }
    }
    if (v === 0) return true;
    for (const l of [-v, v]) {
      const mark = this.trail.length;
      this.set(l);
      if (this.propagate(mark) && this.search()) return true;
      this.undo(mark);
    }
    return false;
  }
}

function dedupe(cl: Lit[]): Lit[] | null {
  const seen = new Set<Lit>();
  const out: Lit[] = [];
  for (const l of cl) {
    if (seen.has(-l)) return null;
    if (!seen.has(l)) {
      seen.add(l);
      out.push(l);
    }
  }
  return out;
}

export interface Result {
  sat: boolean;
  model?: boolean[];
  implied?: Lit[];
}

export function solve(f: CNF, assumptions: Lit[]): Result {
  const s = new Solver(f);
  if (s.empty) return { sat: false };
  if (!s.assume(s.units) || !s.assume(assumptions)) return { sat: false };
  const implied = s.trail.slice();
  if (!s.search()) return { sat: false };
  const model: boolean[] = new Array(s.n + 1).fill(false);
  for (let i = 1; i <= s.n; i++) model[i] = s.assign[i] === 1;
  return { sat: true, model, implied };
}

// mus mirrors catalog.MUS: deletion-based, keeping earlier assumptions.
export function mus(f: CNF, assumptions: Lit[]): Lit[] | null {
  if (solve(f, assumptions).sat) return null;
  let core = assumptions.slice();
  for (let i = core.length - 1; i >= 0; i--) {
    const trial = core.slice(0, i).concat(core.slice(i + 1));
    if (!solve(f, trial).sat) core = trial;
  }
  return core;
}

// Helpers for the builder UI ------------------------------------------------

export interface Selection {
  id: string;
  on: boolean;
}

export interface Check {
  ok: boolean;
  implied: string[]; // options turned on by constraints
  excluded: string[]; // options that can no longer be chosen
  conflict?: string[]; // minimal set of user choices that clash
}

export function check(f: Formula, sel: Selection[]): Check {
  const idx = new Map(f.vars.map((n, i) => [n, i + 1]));
  const lits: Lit[] = [];
  for (const s of sel) {
    const v = idx.get(s.id);
    if (v) lits.push(s.on ? v : -v);
  }
  const r = solve(f.cnf, lits);
  if (!r.sat) {
    const core = mus(f.cnf, lits) ?? [];
    return { ok: false, implied: [], excluded: [], conflict: core.map((l) => f.vars[Math.abs(l) - 1]) };
  }
  const chosen = new Set(sel.filter((s) => s.on).map((s) => s.id));
  const implied = (r.implied ?? []).filter((l) => l > 0).map((l) => f.vars[l - 1]).filter((n) => !chosen.has(n));
  const excluded = (r.implied ?? []).filter((l) => l < 0).map((l) => f.vars[-l - 1]);
  return { ok: true, implied, excluded };
}
